/// <summary>
/// PricingAttribute of table <c>InventTable</c> field SalesPercentMarkup.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableSalesPercentMarkup extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, SalesPercentMarkup);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by SalesPercentMarkup
    {
        if (! ret.in(inventTable.SalesPercentMarkup))
        {
            ret.add(inventTable.SalesPercentMarkup);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, SalesPercentMarkup));
    qbr.value(queryValue(_value));
}
